  return (
    <View className="vehicle-list">
      {vehicles.map((vehicle) => (
        <View className="vehicle-list__item" key={vehicle.id}>
          <Text className="vehicle-list__name">{vehicle.name}</Text>
        </View>
      ))}
    </View>
  );
}

